import unittest
import copy
import yaml


class YamlWriter(object):
    def __init__(self, dict_to_write):
        self.dict_to_write = copy.deepcopy(dict_to_write)
        self.yaml_list = []
        self.parse_emss_dict()

    def split_object_to_class_and_id(self, object_name):
        class_name, id = object_name.split("-", 1)
        return class_name, id

    def parse_emss_dict(self):
        for obj, attributes in sorted(self.dict_to_write.items()):
            class_name, object_id = self.split_object_to_class_and_id(obj)
            attributes["ID"] = object_id
            if "DEL" in attributes:
                attributes["DEL"] = class_name
            else:
                attributes["MOC"] = class_name
            self.yaml_list.append(attributes)

    def write_to_file(self, file_path):
        with open(file_path, "w") as yaml_handler:
            yaml_handler.write(yaml.safe_dump(self.yaml_list, encoding='utf-8', allow_unicode=True, default_flow_style=False).decode('utf-8', 'replace'))


if __name__ == "__main__":
    class TestParsers(unittest.TestCase):
        def test_split_object_to_class_and_id(self):
            writer = YamlWriter({})
            self.assertEqual(writer.split_object_to_class_and_id("LNBTS-88"), ("LNBTS", "88"))
            self.assertEqual(writer.split_object_to_class_and_id("LNREL-1-5"), ("LNREL", "1-5"))

        def test_parse_one_object(self):
            writer = YamlWriter({"LNCEL-1": {"actSdlc": True, "earfcnDL": 9720, "earfcnUL": 27200, }})
            self.assertEqual(writer.yaml_list, [{"MOC": "LNCEL", "ID": "1", "actSdlc": True, "earfcnDL": 9720, "earfcnUL": 27200}])

    unittest.main()
